<?php
namespace Tests\Feature;use Illuminate\Support\Facades\{Route,Schema};use Tests\TestCase;
class TransportControlArchitectureTest extends TestCase {public function test_tran4_schema_routes_and_private_documents_exist():void{foreach(['transport_document_types','transport_documents']as$t)$this->assertTrue(Schema::hasTable($t));$this->assertTrue(Schema::hasColumns('transport_documents',['company_id','resource_type','resource_id','expires_at','file_path','file_hash','is_current']));foreach(['transport.indicators.index','transport.documents.index','transport.history.index','transport.alerts.index','transport.reports.management']as$r)$this->assertTrue(Route::has($r));$this->assertNotSame('public',config('attendance.disk'));}public function test_transport_routes_remain_authenticated():void{$public=collect(Route::getRoutes())->filter(fn($r)=>str_starts_with($r->uri(),'transporte'))->filter(fn($r)=>!in_array('auth',$r->gatherMiddleware()));$this->assertCount(0,$public);}}
